<script setup lang="ts">defineProps<{trace:any;states:string[]}>();</script><template><section class="state-bands"><header><strong>{{trace.reference}} / {{trace.tokens.length}}步</strong><span>完整联合MAP与单点最高态分别显示</span></header><div class="band-scroll"><div class="band-table" :style="{minWidth:Math.max(500,trace.tokens.length*24+125)+'px'}"><div class="band-row"><small>步号 / 观测</small><span v-for="(token,i) in trace.tokens" :key="i" class="token-cell"><em>{{Number(i)+1}}</em>{{token}}</span></div><div class="band-row"><small>Viterbi 联合MAP</small><span v-for="(s,i) in trace.viterbi_path" :key="i" :class="['state-cell','state-'+s]" :title="states[s]">{{s}}</span></div><div class="band-row"><small>单点最高后验</small><span v-for="(s,i) in trace.marginal_path" :key="i" :class="['state-cell','state-'+s]" :title="states[s]">{{s}}</span></div></div></div><div class="state-legend"><span v-for="(s,i) in states" :key="s"><i :class="'state-'+i"></i>{{i}} / {{s}}</span></div><p :class="{copper:!trace.marginal_path_is_legal}">{{trace.marginal_path_is_legal?'本条边际拼接路径可行，但不等于联合MAP定义。':'本条单点最高态拼接违反零概率约束，不能当作合法路径。'}}</p></section></template>
